import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_none_counts_as_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts():
    groups = {"small": [{"flagged": True}], "large": [{"flagged": False}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_window_boundaries():
    counts = [5, 2, 1]
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 2) == 3
    assert flags_in_window(counts, 4) == 8


def test_parse_skips_lines_and_strips_fields():
    assert parse_transcript_log(["", " \t", "  # comment", " a , 1 , 0 ", "b,2, "]) == [
        {"id": "a", "day": 1, "flagged": False},
        {"id": "b", "day": 2, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["id,1", "id,2,0,extra", "id,day,1"])
def test_parse_error_counts_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", " # skipped", "ok,1,1", bad_line])


def test_duplicate_ids_keep_last_input_record_then_sort():
    events = parse_transcript_log(["b,9,1", "c,3,1", "a,2,0", "b,2,0"])
    assert dedupe_transcripts(events) == [events[2], events[3], events[1]]


def test_daily_counts_fill_range_and_ignore_other_days():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,3,0", "e,4,1"])
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": parse_transcript_log(["x,1,1", "y,1,0", "z,4,0"]), "b": []}
    assert monitor_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 1}
    assert monitor_summary({"b": []}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ordering_ties_and_empty_groups():
    groups = {"z": [{"flagged": True}], "b": [], "c": [{"flagged": True}], "a": [{"flagged": False}]}
    assert top_flagged_groups(groups, 2) == ["c", "z"]
    assert top_flagged_groups(groups, 9) == ["c", "z", "a"]
    assert list(flag_rate_by_group(groups).items()) == [("a", 0.0), ("b", None), ("c", 1.0), ("z", 1.0)]


def test_streak_resets_on_nonpositive_days():
    assert longest_flag_streak([1, 0, 2, 3, -1, 4]) == 2
    assert longest_flag_streak([]) == 0
    assert longest_flag_streak([0, -1]) == 0
